from dataclasses import dataclass

from diamond_miner.defaults import UNIVERSE_SUBSET
from diamond_miner.queries.query import (
    PrefixesQuery,
    ResultsQuery,
    prefixes_table,
    results_table,
)
from diamond_miner.typing import IPNetwork


@dataclass(frozen=True)
class GetFarEndTTL():
    
    def statement(
        self, measurement_id: str, max_round: int, subset: IPNetwork = UNIVERSE_SUBSET
    ) -> str:
        return f"""
        SELECT probe_dst_addr, max(probe_ttl) as far_end_ttl FROM (
            SELECT probe_dst_addr, probe_ttl, count(*) as cnt FROM {results_table(measurement_id)}
            WHERE probe_dst_addr != toIPv6('::') AND round != 0 AND probe_ttl != 0
            GROUP BY probe_dst_addr, probe_ttl
            HAVING cnt > {max_round * 0.8}
        )
        GROUP BY probe_dst_addr
        """
